class LoanProcessor {
    public void process(LoanApplication app) {

        if (app.creditScore < 650) {
            System.out.println("Rejected: Credit score too low. Score: " + app.creditScore);
            return;
        }

        if (app.monthlyIncome < app.loanAmount / 36) {
            System.out.println("Rejected: Insufficient monthly income.");
            return;
        }

        if (app.hasExistingDebt) {
            System.out.println("Rejected: Applicant has existing unpaid debt.");
            return;
        }

        if (app.loanAmount > 500000) {
            System.out.println("Rejected: Loan amount exceeds approved limit.");
            return;
        }

        System.out.println("Loan APPROVED for " + app.applicantName);
    }
}

public class Main {
    public static void main(String[] args) {
        LoanApplication app = new LoanApplication(
            "Alice", 720, 8000, 150000, false
        );
        LoanProcessor processor = new LoanProcessor();
        processor.process(app);
    }
}

