abstract class BaseLoanHandler implements LoanHandler {
    private LoanHandler next;

    @Override
    public LoanHandler setNext(LoanHandler next) {
        this.next = next;
        return next; // enables fluent chaining
    }

    protected void forward(LoanApplication app) {
        if (next != null) {
            next.handle(app);
        } else {
            System.out.println("Loan APPROVED for " + app.applicantName);
        }
    }
}

